import urllib.request
# Try SiliconFlow (Chinese LLM API service that supports Gemini)
urls = [
    'https://api.siliconflow.cn/v1/models',
    'https://api.deepseek.com/v1/models',
    'https://open.bigmodel.cn/api/paas/v4/models',
]
for url in urls:
    try:
        req = urllib.request.Request(url, headers={'Authorization': '[REDACTED]'})
        resp = urllib.request.urlopen(req, timeout=5)
        print(f'OK: {url} -> {resp.status}')
    except Exception as e:
        etype = type(e).__name__
        msg = str(e)[:100]
        if 'HTTPError' in etype:
            print(f'REACHABLE (auth err): {url}')
        elif 'timeout' in msg.lower() or 'unreachable' in msg.lower():
            print(f'UNREACHABLE: {url}')
        else:
            print(f'{url} -> {etype}: {msg}')
" 2>&1

