from openai import OpenAI

# Chinese services that are directly reachable work - just need the right key
# Let's try chatanywhere with gemini model to see if they support it
client = OpenAI(
    api_key='[REDACTED]',  # dummy key to test model availability
    base_url='https://api.chatanywhere.tech/v1',
    timeout=10.0,
)
try:
    # Try to list models to see what's supported
    models = client.models.list()
    for m in models:
        if 'gemini' in m.id.lower():
            print(f'Found: {m.id}')
except Exception as e:
    print(f'Models list: {type(e).__name__}: {str(e)[:200]}')

# Also try siliconflow
client2 = OpenAI(
    api_key='[REDACTED]',
    base_url='https://api.siliconflow.cn/v1',
    timeout=10.0,
)
try:
    models = client2.models.list()
    gemini_models = [m.id for m in models if 'gemini' in m.id.lower()]
    if gemini_models:
        print(f'SiliconFlow Gemini models: {gemini_models[:5]}')
    else:
        print(f'SiliconFlow: {len(list(models))} models total, no gemini')
except Exception as e:
    print(f'SiliconFlow models: {type(e).__name__}: {str(e)[:200]}')
" 2>&1
